/* ============================== TOUCH ============================== */

#touch-ui {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  transition: opacity 0.3s;
}

.joystick {
  position: absolute;
  left: calc(24px + env(safe-area-inset-left, 0px));
  bottom: calc(28px + var(--safe-bottom));
  width: 118px;
  height: 118px;
  border-radius: 50%;
  border: 1px solid rgba(199, 161, 91, 0.28);
  background: radial-gradient(circle, rgba(10, 14, 16, 0.45), rgba(5, 7, 9, 0.72));
  box-shadow: inset 0 0 30px rgba(0, 0, 0, 0.4);
  pointer-events: auto;
  touch-action: none;
}

.joystick::before,
.joystick::after {
  content: '';
  position: absolute;
  background: rgba(199, 161, 91, 0.13);
}

.joystick::before { left: 50%; top: 12px; bottom: 12px; width: 1px; }
.joystick::after { top: 50%; left: 12px; right: 12px; height: 1px; }

.joystick-stick {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 48px;
  height: 48px;
  margin: -24px 0 0 -24px;
  border-radius: 50%;
  border: 1px solid rgba(199, 161, 91, 0.5);
  background: radial-gradient(circle, rgba(199, 161, 91, 0.2), rgba(10, 14, 16, 0.85));
  box-shadow: 0 0 18px rgba(199, 161, 91, 0.14);
}

.touch-buttons {
  position: absolute;
  right: calc(22px + env(safe-area-inset-right, 0px));
  bottom: calc(30px + var(--safe-bottom));
  display: grid;
  grid-template-columns: repeat(2, 62px);
  gap: 10px;
  pointer-events: auto;
}

.touch-btn {
  position: relative;
  width: 62px;
  height: 62px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(199, 161, 91, 0.32);
  background: radial-gradient(circle, rgba(20, 25, 27, 0.85), rgba(5, 7, 9, 0.9));
  color: var(--gold);
  box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.4), 0 4px 14px rgba(0, 0, 0, 0.35);
  touch-action: none;
}

.touch-btn svg { width: 24px; height: 24px; }
.touch-btn:active { background: rgba(199, 161, 91, 0.18); }
.touch-btn b {
  position: absolute;
  right: 5px;
  bottom: 3px;
  font-family: var(--display);
  font-size: 0.55rem;
  color: var(--bone);
}
.touch-attack { grid-column: 2; grid-row: 2; width: 72px; height: 72px; }
.touch-dodge { grid-column: 1; grid-row: 2; }
.touch-flask { grid-column: 2; grid-row: 1; }
.touch-use { grid-column: 1; grid-row: 1; }

.touch-menu {
  position: absolute;
  right: calc(22px + env(safe-area-inset-right, 0px));
  top: calc(92px + var(--safe-top));
  padding: 7px 10px;
  border: 1px solid rgba(199, 161, 91, 0.28);
  background: rgba(5, 7, 9, 0.65);
  font-family: var(--display);
  font-size: 0.42rem;
  letter-spacing: 0.14em;
  color: var(--gold);
  pointer-events: auto;
}

/* ============================== LOADING ============================== */

.loading-screen {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  background:
    radial-gradient(circle at center, rgba(22, 30, 31, 0.2), transparent 40%),
    #030506;
  transition: opacity 0.8s ease, visibility 0.8s;
}

.loading-screen.done {
  opacity: 0;
  visibility: hidden;
}

.loading-crest {
  width: 66px;
  height: 66px;
  color: var(--gold);
  opacity: 0.7;
  animation: crest-breathe 2.6s ease-in-out infinite;
}

.loading-crest svg { width: 100%; height: 100%; stroke-width: 1.2; }

@keyframes crest-breathe {
  0%, 100% { opacity: 0.4; filter: drop-shadow(0 0 2px rgba(199, 161, 91, 0)); }
  50% { opacity: 0.9; filter: drop-shadow(0 0 14px rgba(199, 161, 91, 0.35)); }
}

.loading-screen p {
  margin: 0;
  font-family: var(--display);
  font-size: 0.5rem;
  letter-spacing: 0.36em;
  color: var(--gold);
}

.loading-line {
  width: 190px;
  height: 1px;
  background: rgba(199, 161, 91, 0.15);
  overflow: hidden;
}

.loading-line i {
  display: block;
  width: 40%;
  height: 100%;
  background: linear-gradient(90deg, transparent, var(--gold-bright), transparent);
  animation: loading-sweep 1.4s ease-in-out infinite;
}

@keyframes loading-sweep {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(350%); }
}

