  const steel = mat(0x8e9797, { roughness: 0.33, metalness: 0.88, emissive: 0x0c1010, emissiveIntensity: 0.2 })
  const darkSteel = mat(0x343b3b, { roughness: 0.46, metalness: 0.78 })
  const brass = mat(0x8a6a35, { roughness: 0.36, metalness: 0.82, emissive: 0x2b1b06, emissiveIntensity: 0.15 })
  const skin = mat(0x8b7867, { roughness: 0.8 })
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0x7ce3d7 })
  const flashMats = [leather, darkCloth, innerCloth, steel, darkSteel, brass, skin]

  const hips = new THREE.Group()
  hips.position.y = 0.94
  rig.add(hips)

  const belt = mesh(new THREE.CylinderGeometry(0.31, 0.33, 0.14, 10), leather, 0, 0.08, 0)
