  head.add(hoodCone)

  const faceShadow = mesh(new THREE.SphereGeometry(0.148, 10, 8), new THREE.MeshBasicMaterial({ color: 0x020303 }), 0, 0.08, 0.14)
  faceShadow.scale.set(1, 1.05, 0.4)
