  // Lantern
  const lantern = new THREE.Group()
  lantern.position.set(-0.33, 0.05, 0.04)
  hips.add(lantern)
  const lanternBody = mesh(new THREE.CylinderGeometry(0.06, 0.07, 0.16, 6), darkSteel, 0, 0, 0)
  lantern.add(lanternBody)
  const lanternGlow = glowSprite(textures.glow, 0xffa95a, 0.55, 0.7)
  lanternGlow.position.y = 0
  lantern.add(lanternGlow)
  const lanternLight = new THREE.PointLight(0xff9f55, 0.85, 5.5, 2)
  lanternLight.position.y = 0
  lantern.add(lanternLight)

  // Grounding shadow-ish disc
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.45, 20),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.3, depthWrite: false })
  )
  shadow.rotation.x = -Math.PI / 2
  shadow.position.y = 0.01
  group.add(shadow)

  group.userData.rig = rig
  scene.add(group)

  return {
    group,
    rig,
    hips,
    torso,
    head,
    leftArm,
    rightArm,
    leftLeg,
    rightLeg,
    leftFore: leftArm.userData.fore,
    rightFore: rightArm.userData.fore,
    sword,
    edge,
    swordGlow,
    lantern,
    lanternLight,
    eyeGlow,
    eyeMat,
    flashMats,
    materials: { steel, brass, darkCloth, leather, innerCloth, darkSteel },
  }
}

function makeHealthBar() {
  const group = new THREE.Group()
  const back = new THREE.Mesh(
    new THREE.PlaneGeometry(1.1, 0.12),
    new THREE.MeshBasicMaterial({ color: 0x050606, transparent: true, opacity: 0.82, depthWrite: false })
  )
  const fill = new THREE.Mesh(
    new THREE.PlaneGeometry(1.02, 0.065),
    new THREE.MeshBasicMaterial({ color: 0xa32930, depthWrite: false })
  )
  fill.position.z = 0.002
  const glint = new THREE.Mesh(
    new THREE.PlaneGeometry(1.02, 0.018),
    new THREE.MeshBasicMaterial({ color: 0xff8c83, transparent: true, opacity: 0.45, depthWrite: false })
  )
  glint.position.set(0, 0.02, 0.003)
  group.add(back, fill, glint)
  group.visible = false
  return { group, fill, glint, back }
}

export function createEnemy(scene, type, x, z, textures) {
  const group = new THREE.Group()
  group.position.set(x, 0, z)
  const rig = new THREE.Group()
  group.add(rig)

  const isBrute = type === 'brute'
  const isWisp = type === 'wisp'
  const scale = isBrute ? 1.38 : isWisp ? 1 : 1

  const clothColor = isBrute ? 0x2a1a17 : isWisp ? 0x172527 : 0x20261f
  const cloth = mat(clothColor, { roughness: 0.98, side: THREE.DoubleSide })
  const leather = mat(isBrute ? 0x2e1c16 : 0x1b1c18, { roughness: 0.94 })
  const bone = mat(0x9b9787, { roughness: 0.78 })
  const iron = mat(0x3d4140, { roughness: 0.55, metalness: 0.66 })
  const eyeColor = isBrute ? 0xff4b3e : isWisp ? 0x78d8ff : 0x73e2cf
  const eyeMat = new THREE.MeshBasicMaterial({ color: eyeColor })
  const flashMats = [cloth, leather, bone, iron]

  const body = new THREE.Group()
  body.position.y = 0.92
  rig.add(body)

  const torso = mesh(new THREE.CylinderGeometry(isBrute ? 0.4 : 0.24, isBrute ? 0.3 : 0.2, isBrute ? 0.8 : 0.7, 8), cloth, 0, isBrute ? 0.35 : 0.33, 0)
  torso.rotation.x = isBrute ? 0.04 : 0.13
  body.add(torso)

  if (!isWisp) {
    const rib = mesh(new THREE.TorusGeometry(isBrute ? 0.28 : 0.18, 0.025, 4, 10), bone, 0, 0.42, 0.03)
    rib.rotation.x = Math.PI / 2
    rib.scale.y = 1.4
    body.add(rib)
  }

  const shoulders = mesh(new THREE.BoxGeometry(isBrute ? 0.86 : 0.52, 0.11, 0.24), leather, 0, isBrute ? 0.68 : 0.61, 0)
  body.add(shoulders)

  // Head
  const head = new THREE.Group()
  head.position.set(0, isBrute ? 0.83 : 0.72, isWisp ? 0 : 0.05)
  body.add(head)

  const skull = mesh(new THREE.SphereGeometry(isBrute ? 0.2 : 0.15, 9, 7), isWisp ? cloth : bone, 0, 0.03, 0)
  skull.scale.set(0.9, 1.05, 0.82)
  head.add(skull)

  const hood = mesh(new THREE.SphereGeometry(isBrute ? 0.26 : 0.2, 10, 8), cloth, 0, 0.02, -0.02)
  hood.scale.set(1, 1.08, 1)
  head.add(hood)

  const jaw = mesh(new THREE.BoxGeometry(isBrute ? 0.16 : 0.11, 0.06, 0.1), bone, 0, -0.08, 0.1)
  head.add(jaw)

  const eyeL = mesh(new THREE.SphereGeometry(0.022, 5, 4), eyeMat, -0.055, 0.04, 0.14, false)
  const eyeR = mesh(new THREE.SphereGeometry(0.022, 5, 4), eyeMat, 0.055, 0.04, 0.14, false)
  head.add(eyeL, eyeR)
  const glow = glowSprite(textures.glow, eyeColor, isBrute ? 0.5 : 0.32, 0.4)
  glow.position.set(0, 0.04, 0.17)
  head.add(glow)

  if (isBrute) {
    for (const side of [-1, 1]) {
      const horn = mesh(new THREE.ConeGeometry(0.055, 0.35, 5), bone, side * 0.18, 0.2, -0.02)
      horn.rotation.z = side * 0.72
      horn.rotation.x = -0.15
      head.add(horn)
    }
  }

  // Legs
  let leftLeg = null
  let rightLeg = null
  if (!isWisp) {
    leftLeg = new THREE.Group()
    leftLeg.position.set(-0.14, 0.88, 0)
    rightLeg = new THREE.Group()
    rightLeg.position.set(0.14, 0.88, 0)
    rig.add(leftLeg, rightLeg)
    for (const leg of [leftLeg, rightLeg]) {
      const thigh = limb(isBrute ? 0.42 : 0.46, isBrute ? 0.12 : 0.075, 0.06, leather)
      thigh.position.y = -0.23
      leg.add(thigh)
      const shin = limb(isBrute ? 0.4 : 0.44, 0.06, 0.045, cloth)
      shin.position.y = -0.65
      leg.add(shin)
      const foot = mesh(new THREE.BoxGeometry(0.16, 0.11, 0.3), leather, 0, -0.9, 0.07)
      leg.add(foot)
    }
  } else {
    const tail = mesh(new THREE.ConeGeometry(0.34, 1.15, 8, 1, true), cloth, 0, 0.35, 0)
    tail.position.y = 0.35
    tail.rotation.x = Math.PI
    rig.add(tail)
    const wispGlow = glowSprite(textures.glow, eyeColor, 1.8, 0.22)
    wispGlow.position.y = 1.0
    rig.add(wispGlow)
  }

  // Arms
  const leftArm = new THREE.Group()
  leftArm.position.set(isBrute ? -0.46 : -0.3, isBrute ? 0.62 : 0.55, 0)
  const rightArm = new THREE.Group()
  rightArm.position.set(isBrute ? 0.46 : 0.3, isBrute ? 0.62 : 0.55, 0)
  body.add(leftArm, rightArm)

  for (const arm of [leftArm, rightArm]) {
    const upper = limb(isBrute ? 0.42 : 0.35, isBrute ? 0.105 : 0.06, 0.05, isWisp ? cloth : leather)
    upper.position.y = -0.18
    arm.add(upper)
    const fore = new THREE.Group()
    fore.position.y = -0.37
    arm.add(fore)
    const foreMesh = limb(isBrute ? 0.36 : 0.3, 0.052, 0.038, cloth)
    foreMesh.position.y = -0.15
    fore.add(foreMesh)
    const claw = mesh(new THREE.ConeGeometry(0.06, 0.16, 5), bone, 0, -0.34, 0.02)
    claw.rotation.x = Math.PI
    fore.add(claw)
    arm.userData.fore = fore
  }

  // Weapon
  const weapon = new THREE.Group()
  weapon.position.set(0, -0.31, 0.03)
  rightArm.userData.fore.add(weapon)
  if (isBrute) {
    const handle = mesh(new THREE.CylinderGeometry(0.04, 0.05, 1.15, 6), leather, 0, 0.42, 0)
    weapon.add(handle)
    const headBlock = mesh(new THREE.BoxGeometry(0.42, 0.32, 0.3), iron, 0, 0.98, 0)
    weapon.add(headBlock)
    const spike = mesh(new THREE.ConeGeometry(0.09, 0.26, 5), iron, 0, 1.22, 0)
    weapon.add(spike)
  } else if (!isWisp) {
    const handle = mesh(new THREE.CylinderGeometry(0.022, 0.028, 0.3, 6), leather, 0, 0.06, 0)
    weapon.add(handle)
    const cleaver = mesh(new THREE.BoxGeometry(0.07, 0.65, 0.02), iron, 0, 0.48, 0)
    cleaver.rotation.z = 0.12
    weapon.add(cleaver)
    const hook = mesh(new THREE.BoxGeometry(0.16, 0.08, 0.022), iron, 0.07, 0.73, 0)
    weapon.add(hook)
  } else {
    const orb = mesh(new THREE.SphereGeometry(0.11, 9, 7), new THREE.MeshBasicMaterial({ color: eyeColor }), 0, 0.05, 0, false)
    weapon.add(orb)
    const orbGlow = glowSprite(textures.glow, eyeColor, 0.9, 0.6)
    orbGlow.position.y = 0.05
    weapon.add(orbGlow)
  }

  const cloak = tatteredCloak(cloth, isBrute ? 1.1 : 0.86, isBrute ? 1.15 : 1.0, 0.08)
  cloak.position.set(0, 0.4, -0.18)
  cloak.rotation.x = 0.1
  body.add(cloak)

  // Telegraph ring
  const telegraph = new THREE.Mesh(
    new THREE.RingGeometry(0.55, 0.7, 24),
    new THREE.MeshBasicMaterial({ color: 0xff3d35, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
  )
  telegraph.rotation.x = -Math.PI / 2
  telegraph.position.y = 0.03
  group.add(telegraph)

  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(isBrute ? 0.5 : 0.36, 16),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.32, depthWrite: false })
  )
  shadow.rotation.x = -Math.PI / 2
  shadow.position.y = 0.005
  group.add(shadow)

  group.scale.setScalar(scale)
  scene.add(group)

  const bar = makeHealthBar()
  scene.add(bar.group)

  return {
    type,
    group,
    rig,
    body,
    head,
    leftArm,
    rightArm,
    leftLeg,
    rightLeg,
    leftFore: leftArm.userData.fore,
    rightFore: rightArm.userData.fore,
    weapon,
    cloak,
    telegraph,
    eyeMat,
    glow,
    flashMats,
    bar,
    baseY: 0,
  }
}

export function createBoss(scene, x, z, textures) {
  const group = new THREE.Group()
  group.position.set(x, 0, z)
  const rig = new THREE.Group()
  group.add(rig)

  const bone = mat(0xa29d8c, { roughness: 0.72 })
  const oldBone = mat(0x746f60, { roughness: 0.85 })
  const iron = mat(0x3c3f3d, { roughness: 0.42, metalness: 0.82 })
  const brass = mat(0x7a5c2e, { roughness: 0.4, metalness: 0.8 })
  const cloth = mat(0x1c1211, { roughness: 0.96, side: THREE.DoubleSide })
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0xff4137 })
  const flashMats = [bone, oldBone, iron, brass, cloth]

  const pelvis = new THREE.Group()
  pelvis.position.y = 1.2
  rig.add(pelvis)

  const pelvisMesh = mesh(new THREE.BoxGeometry(0.55, 0.24, 0.34), oldBone, 0, 0, 0)
  pelvis.add(pelvisMesh)

  // Legs
  const leftLeg = new THREE.Group()
  leftLeg.position.set(-0.2, 1.18, 0)
  const rightLeg = new THREE.Group()
  rightLeg.position.set(0.2, 1.18, 0)
  rig.add(leftLeg, rightLeg)
  for (const leg of [leftLeg, rightLeg]) {
    const thigh = limb(0.52, 0.12, 0.1, oldBone)
    thigh.position.y = -0.26
    leg.add(thigh)
    const knee = mesh(new THREE.SphereGeometry(0.13, 7, 6), iron, 0, -0.53, 0.02)
    leg.add(knee)
    const shin = limb(0.52, 0.1, 0.08, oldBone)
    shin.position.y = -0.77
    leg.add(shin)
    const sabaton = mesh(new THREE.BoxGeometry(0.27, 0.19, 0.47), iron, 0, -1.07, 0.09)
    leg.add(sabaton)
    const spike = mesh(new THREE.ConeGeometry(0.06, 0.2, 5), iron, 0, -1.04, 0.36)
    spike.rotation.x = 1.1
    leg.add(spike)
  }

  // Torso
  const torso = new THREE.Group()
  torso.position.y = 1.55
  rig.add(torso)

  const spine = mesh(new THREE.CylinderGeometry(0.09, 0.12, 1.1, 6), oldBone, 0, 0.25, -0.02)
  torso.add(spine)

  for (let i = 0; i < 4; i++) {
    const rib = mesh(new THREE.TorusGeometry(0.32 - i * 0.025, 0.035, 5, 12), bone, 0, 0.12 + i * 0.2, 0.02)
    rib.rotation.x = Math.PI / 2
    rib.scale.y = 0.72
    torso.add(rib)
  }

  const chest = mesh(new THREE.BoxGeometry(0.62, 0.36, 0.34), iron, 0, 0.62, 0.04)
  chest.rotation.x = -0.12
  torso.add(chest)

  const chestRune = new THREE.Mesh(
    new THREE.PlaneGeometry(0.15, 0.24),
    new THREE.MeshBasicMaterial({ color: 0xff5b47, transparent: true, opacity: 0.75, blending: THREE.AdditiveBlending, depthWrite: false })
  )
  chestRune.position.set(0, 0.62, 0.23)
  torso.add(chestRune)

  for (const side of [-1, 1]) {
    const pauldron = mesh(new THREE.SphereGeometry(0.26, 9, 7), iron, side * 0.45, 0.7, 0)
    pauldron.scale.set(1.2, 0.66, 1.05)
    torso.add(pauldron)
    const pauldronSpike = mesh(new THREE.ConeGeometry(0.075, 0.4, 5), iron, side * 0.62, 0.82, 0)
    pauldronSpike.rotation.z = side * 0.8
    torso.add(pauldronSpike)
    const rim = mesh(new THREE.TorusGeometry(0.23, 0.018, 4, 10), brass, side * 0.45, 0.72, 0)
    rim.rotation.x = Math.PI / 2
    torso.add(rim)
  }

  // Skull head
  const head = new THREE.Group()
  head.position.y = 1.03
  torso.add(head)

  const skull = mesh(new THREE.SphereGeometry(0.22, 10, 8), bone, 0, 0.04, 0.02)
  skull.scale.set(0.9, 1.05, 0.9)
  head.add(skull)
  const jaw = mesh(new THREE.BoxGeometry(0.23, 0.12, 0.18), oldBone, 0, -0.13, 0.08)
  head.add(jaw)
  const teeth = mesh(new THREE.BoxGeometry(0.2, 0.035, 0.04), bone, 0, -0.07, 0.16)
  head.add(teeth)

  const eyeL = mesh(new THREE.SphereGeometry(0.032, 5, 4), eyeMat, -0.085, 0.06, 0.18, false)
  const eyeR = mesh(new THREE.SphereGeometry(0.032, 5, 4), eyeMat, 0.085, 0.06, 0.18, false)
  head.add(eyeL, eyeR)
  const eyeGlow = glowSprite(textures.glow, 0xff3f34, 0.9, 0.6)
  eyeGlow.position.set(0, 0.06, 0.2)
  head.add(eyeGlow)

  // Crown/helm
  const helm = mesh(new THREE.CylinderGeometry(0.26, 0.24, 0.22, 8), iron, 0, 0.18, -0.02)
  head.add(helm)
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU
    const spike = mesh(new THREE.ConeGeometry(0.035, 0.24 + (i % 2) * 0.12, 5), brass, Math.cos(a) * 0.2, 0.36, Math.sin(a) * 0.2 - 0.02)
    spike.rotation.z = Math.cos(a) * 0.2
    spike.rotation.x = -Math.sin(a) * 0.2
    head.add(spike)
  }

  // Arms
  const leftArm = new THREE.Group()
  leftArm.position.set(-0.52, 0.66, 0)
  const rightArm = new THREE.Group()
  rightArm.position.set(0.52, 0.66, 0)
  torso.add(leftArm, rightArm)

  for (const arm of [leftArm, rightArm]) {
    const upper = limb(0.52, 0.1, 0.08, oldBone)
    upper.position.y = -0.26
    arm.add(upper)
    const elbow = mesh(new THREE.SphereGeometry(0.11, 7, 6), iron, 0, -0.54, 0)
    arm.add(elbow)
    const fore = new THREE.Group()
    fore.position.y = -0.55
    arm.add(fore)
    const foreMesh = limb(0.5, 0.075, 0.055, oldBone)
    foreMesh.position.y = -0.24
    fore.add(foreMesh)
    const bracer = mesh(new THREE.CylinderGeometry(0.1, 0.085, 0.26, 6), iron, 0, -0.28, 0)
    fore.add(bracer)
    const hand = mesh(new THREE.BoxGeometry(0.14, 0.18, 0.13), oldBone, 0, -0.51, 0.02)
    fore.add(hand)
    arm.userData.fore = fore
  }

  // Great axe
  const axe = new THREE.Group()
  axe.position.set(0, -0.46, 0.02)
  axe.rotation.z = -0.1
  rightArm.userData.fore.add(axe)
  const haft = mesh(new THREE.CylinderGeometry(0.045, 0.055, 2.5, 6), cloth, 0, 0.65, 0)
  axe.add(haft)
  const haftWrap = mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.45, 6), leather, 0, 0.05, 0)
  axe.add(haftWrap)
  const axeHead = mesh(new THREE.BoxGeometry(0.8, 0.5, 0.1), iron, 0, 1.74, 0)
  axe.add(axeHead)
  const axeBlade = mesh(new THREE.CylinderGeometry(0.48, 0.3, 0.1, 3), iron, 0, 1.74, 0)
  axeBlade.rotation.y = Math.PI / 2
  axeBlade.rotation.z = Math.PI / 2
  axeBlade.scale.set(1, 0.3, 0.6)
  axe.add(axeBlade)
  const axeGlow = glowSprite(textures.glow, 0xff3f34, 1.5, 0.2)
  axeGlow.position.y = 1.7
  axe.add(axeGlow)

  // Tattered cloak
  const cloak = tatteredCloak(cloth, 1.6, 2.1, 0.16)
  cloak.position.set(0, 0.35, -0.32)
  cloak.rotation.x = 0.12
  torso.add(cloak)

  // Aura ring
  const aura = new THREE.Mesh(
    new THREE.RingGeometry(1.0, 1.2, 40),
    new THREE.MeshBasicMaterial({ color: 0xa32930, transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
  )
  aura.rotation.x = -Math.PI / 2
  aura.position.y = 0.02
  group.add(aura)

  const telegraph = new THREE.Mesh(
    new THREE.RingGeometry(0.7, 0.92, 32),
    new THREE.MeshBasicMaterial({ color: 0xff3d35, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
  )
  telegraph.rotation.x = -Math.PI / 2
  telegraph.position.y = 0.035
  group.add(telegraph)

  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.9, 24),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.45, depthWrite: false })
  )
  shadow.rotation.x = -Math.PI / 2
  shadow.position.y = 0.005
  group.add(shadow)

  const light = new THREE.PointLight(0xff3b2f, 1.5, 10, 2)
  light.position.set(0, 2.6, 0.5)
  group.add(light)

  group.scale.setScalar(1.9)
  scene.add(group)

  const bar = makeHealthBar()
  scene.add(bar.group)

  return {
    type: 'boss',
    group,
    rig,
    torso,
    head,
    leftArm,
    rightArm,
    leftLeg,
    rightLeg,
    leftFore: leftArm.userData.fore,
    rightFore: rightArm.userData.fore,
    axe,
    axeGlow,
    cloak,
    aura,
    telegraph,
    eyeMat,
    eyeGlow,
    flashMats,
    bar,
    light,
    baseY: 0,
  }
}

export class GameAudio {
  constructor() {
    this.ctx = null
    this.master = null
    this.reverb = null
    this.ambient = null
    this.muted = false
    this.ready = false
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    this.ctx = new Ctx()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.72
    this.master.connect(this.ctx.destination)

    // A small, dark plate reverb for atmosphere.
    const seconds = 1.8
    const rate = this.ctx.sampleRate
    const length = rate * seconds
    const impulse = this.ctx.createBuffer(2, length, rate)
    for (let channel = 0; channel < 2; channel++) {
      const data = impulse.getChannelData(channel)
      for (let i = 0; i < length; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, 3.4)
      }
    }
    this.reverb = this.ctx.createConvolver()
    this.reverb.buffer = impulse
    const wet = this.ctx.createGain()
    wet.gain.value = 0.32
    this.reverb.connect(wet)
    wet.connect(this.master)

    this.startAmbience()
    this.ready = true
  }

  setMuted(value) {
    this.muted = value
    if (this.master) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime)
      this.master.gain.linearRampToValueAtTime(value ? 0 : 0.72, this.ctx.currentTime + 0.15)
    }
  }

  toggle() {
    this.setMuted(!this.muted)
    return this.muted
  }

  connect(node, wet = 0.35) {
    node.connect(this.master)
    if (this.reverb) {
      const send = this.ctx.createGain()
      send.gain.value = wet
      node.connect(send)
      send.connect(this.reverb)
    }
  }

  tone(freq, duration, type = 'sine', gain = 0.05, when = 0, slideTo = null) {
    if (!this.ctx || this.muted) return
    const t = this.ctx.currentTime + when
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + duration)
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    osc.connect(g)
    this.connect(g, 0.3)
    osc.start(t)
    osc.stop(t + duration + 0.03)
  }

  noise(duration, freq, gain = 0.05, when = 0, q = 0.8, type = 'bandpass', sweepTo = null) {
    if (!this.ctx || this.muted) return
    const t = this.ctx.currentTime + when
    const rate = this.ctx.sampleRate
    const length = Math.max(1, Math.floor(rate * duration))
    const buffer = this.ctx.createBuffer(1, length, rate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
    const src = this.ctx.createBufferSource()
    src.buffer = buffer
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.setValueAtTime(freq, t)
    if (sweepTo) filter.frequency.exponentialRampToValueAtTime(sweepTo, t + duration)
    filter.Q.value = q
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + 0.015)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    src.connect(filter)
    filter.connect(g)
    this.connect(g, 0.28)
    src.start(t)
    src.stop(t + duration + 0.03)
  }

  startAmbience() {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const bus = this.ctx.createGain()
    bus.gain.value = 0.55
    this.connect(bus, 0.65)

    const low = this.ctx.createOscillator()
    low.type = 'sine'
    low.frequency.value = 43.65
    const lowGain = this.ctx.createGain()
    lowGain.gain.value = 0.038
    low.connect(lowGain)
    lowGain.connect(bus)
    low.start(t)

    const fifth = this.ctx.createOscillator()
    fifth.type = 'triangle'
    fifth.frequency.value = 65.41
    const fifthGain = this.ctx.createGain()
    fifthGain.gain.value = 0.016
    fifth.connect(fifthGain)
    fifthGain.connect(bus)
    fifth.start(t)

    const high = this.ctx.createOscillator()
    high.type = 'sine'
    high.frequency.value = 174.61
    const highGain = this.ctx.createGain()
    highGain.gain.value = 0.0035
    const highLfo = this.ctx.createOscillator()
    highLfo.frequency.value = 0.07
    const highLfoGain = this.ctx.createGain()
    highLfoGain.gain.value = 0.003
    highLfo.connect(highLfoGain)
    highLfoGain.connect(highGain.gain)
    high.connect(highGain)
    highGain.connect(bus)
    high.start(t)
    highLfo.start(t)

    // Wind bed
    const rate = this.ctx.sampleRate
    const length = rate * 4
    const buffer = this.ctx.createBuffer(1, length, rate)
    const data = buffer.getChannelData(0)
    let last = 0
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1
      last = (last + 0.02 * white) / 1.02
      data[i] = last * 3.2
    }
    const wind = this.ctx.createBufferSource()
    wind.buffer = buffer
    wind.loop = true
    const windFilter = this.ctx.createBiquadFilter()
    windFilter.type = 'lowpass'
    windFilter.frequency.value = 520
    windFilter.Q.value = 0.4
    const windGain = this.ctx.createGain()
    windGain.gain.value = 0.05
    const windLfo = this.ctx.createOscillator()
    windLfo.frequency.value = 0.055
    const windLfoGain = this.ctx.createGain()
    windLfoGain.gain.value = 0.022
    windLfo.connect(windLfoGain)
    windLfoGain.connect(windGain.gain)
    wind.connect(windFilter)
    windFilter.connect(windGain)
    windGain.connect(bus)
    wind.start(t)
    windLfo.start(t)

    this.ambient = { bus, low, fifth, high, wind }
  }

  swing(heavy = false) {
    this.noise(heavy ? 0.4 : 0.26, heavy ? 380 : 620, heavy ? 0.13 : 0.085, 0, 1.1, 'bandpass', heavy ? 120 : 240)
    this.tone(heavy ? 110 : 160, 0.12, 'triangle', 0.025, 0, heavy ? 70 : 110)
  }

  hit(crit = false) {
    this.noise(0.16, crit ? 1600 : 900, crit ? 0.13 : 0.08, 0, 0.7, 'bandpass', 180)
    this.tone(crit ? 72 : 58, 0.24, 'sine', 0.15, 0, 34)
    if (crit) this.tone(980, 0.12, 'square', 0.025, 0.01, 620)
  }

  hurt() {
    this.tone(92, 0.4, 'sawtooth', 0.1, 0, 38)
    this.noise(0.32, 240, 0.12, 0, 0.9, 'lowpass', 90)
  }

  pickup(rare = false) {
    const base = rare ? 523.25 : 659.25
    this.tone(base, 0.18, 'sine', 0.045)
    this.tone(base * 1.5, 0.24, 'sine', 0.03, 0.06)
    if (rare) this.tone(base * 2, 0.36, 'sine', 0.025, 0.14)
  }

  craft() {
    this.noise(0.5, 1800, 0.06, 0, 2.4, 'bandpass', 420)
    this.tone(130.81, 0.7, 'triangle', 0.09, 0)
    this.tone(196, 0.9, 'sine', 0.05, 0.12)
    this.tone(261.63, 1.2, 'sine', 0.035, 0.24)
  }

  flask() {
    this.tone(310, 0.25, 'sine', 0.04, 0, 460)
    this.tone(620, 0.4, 'sine', 0.025, 0.08)
    this.noise(0.18, 1300, 0.025, 0.04, 1.4)
  }

  levelUp() {
    const notes = [261.63, 329.63, 392, 523.25]
    notes.forEach((n, i) => this.tone(n, 1.2, 'sine', 0.035, i * 0.1))
    this.tone(65.41, 1.8, 'triangle', 0.06, 0)
  }

  wave() {
    this.tone(55, 1.8, 'sine', 0.13, 0, 41)
    this.tone(110, 1.4, 'triangle', 0.045, 0.1)
    this.noise(1.2, 180, 0.05, 0, 0.8, 'lowpass')
  }

  bossRoar() {
    this.tone(46, 1.8, 'sawtooth', 0.18, 0, 31)
    this.tone(69, 1.4, 'square', 0.07, 0.05, 42)
    this.noise(1.6, 420, 0.12, 0, 0.6, 'lowpass', 80)
  }

  death() {
    this.tone(98, 2.2, 'sine', 0.1, 0, 32)
    this.tone(49, 2.6, 'triangle', 0.12, 0.1, 24)
    this.noise(2.0, 300, 0.08, 0, 0.7, 'lowpass', 60)
  }

  victory() {
    const notes = [130.81, 164.81, 196, 261.63, 329.63]
    notes.forEach((n, i) => this.tone(n, 2.8, 'sine', 0.045, i * 0.22))
    this.tone(65.41, 4, 'triangle', 0.06, 0)
  }

  ui() {
    this.tone(720, 0.06, 'sine', 0.018, 0, 600)
  }
}

input.newString:
function hideAllScreens() {
  hideScreen(ui.title)
  hideScreen(ui.satchel)
  hideScreen(ui.pause)
  hideScreen(ui.death)
  hideScreen(ui.victory)
}

function recalcStats(healDelta = true) {
  const oldMax = player.maxHp
  player.maxHp = 120 + (player.upgrades.cuirass ? 40 : 0) + (player.level - 1) * 10
  player.damage = 18 + (player.upgrades.blade ? 12 : 0) + player.upgrades.whetstones * 6 + (player.level - 1) * 2
  player.maxFlasks = 3 + player.upgrades.flasks
  player.damageReduction = (player.upgrades.charm ? 0.2 : 0) + (player.upgrades.cuirass ? 0.05 : 0)
  if (healDelta && player.maxHp > oldMax) player.hp += player.maxHp - oldMax
  player.hp = clamp(player.hp, 1, player.maxHp)
  player.flasks = clamp(player.flasks, 0, player.maxFlasks)
  updateSwordVisuals()
}

function updateSwordVisuals() {
  const blade = player.upgrades.blade
  avatar.edge.material.color.setHex(blade ? 0xffc875 : 0x6f8f8d)
  avatar.swordGlow.material.color.setHex(blade ? 0xffa548 : 0x62c7bc)
  avatar.swordGlow.material.opacity = blade ? 0.35 : 0
  avatar.materials.steel.emissive.setHex(blade ? 0x3a1c06 : 0x0c1010)
  avatar.materials.steel.emissiveIntensity = blade ? 0.55 : 0.2
}

function updateHUD() {
  const hpPct = clamp(player.hp / player.maxHp, 0, 1)
  ui.hpFill.style.width = `${hpPct * 100}%`
  ui.hpText.textContent = `${Math.ceil(player.hp)} / ${player.maxHp}`
  ui.staminaFill.style.width = `${clamp(player.stamina / player.maxStamina, 0, 1) * 100}%`
  ui.xpFill.style.width = `${clamp(player.essence / player.essenceNext, 0, 1) * 100}%`
  ui.xpText.textContent = `SOUL ESSENCE ${Math.floor(player.essence)}`
  ui.levelPill.textContent = `SOUL ${roman(player.level)}`
  ui.shardCount.textContent = String(player.inventory.shard)
  ui.killCount.textContent = String(GAME.kills)
  ui.flaskCount.textContent = String(player.flasks)
  ui.touchFlasks.textContent = String(player.flasks)
  ui.weaponTag.textContent = player.upgrades.blade ? 'EMBERFORGED' : 'RUSTED EDGE'
  ui.charmTag.textContent = player.upgrades.charm ? 'GRAVEWARD' : 'NO CHARM'
  if (GAME.boss && !GAME.boss.dead) {
    ui.bossFill.style.width = `${clamp(GAME.boss.hp / GAME.boss.maxHp, 0, 1) * 100}%`
  }
}

function addResource(type, amount) {
  if (!amount) return
  if (type === 'shard') {
    player.inventory.shard += amount
    GAME.totalShards += amount
  } else {
    player.inventory[type] = (player.inventory[type] || 0) + amount
  }
  updateHUD()
}

function gainEssence(amount) {
  player.essence += amount
  let leveled = false
  while (player.essence >= player.essenceNext) {
    player.essence -= player.essenceNext
    player.level += 1
    player.essenceNext = Math.round(player.essenceNext * 1.34)
    leveled = true
  }
  if (leveled) {
    recalcStats(true)
    player.hp = Math.min(player.maxHp, player.hp + 25)
    player.stamina = player.maxStamina
    showToast('i-spark', `<b>SOUL ASCENDED</b> — Level ${roman(player.level)}`, true)
    spawnSoulBurst(player.group.position.clone().setY(1.1), 0xffd782, 28)
    spawnRing(player.group.position.clone().setY(0.08), 0xffd782, 0.4, 3.2, 1.1, 0.55)
    audio.levelUp()
  }
  updateHUD()
}

function spawnLoot(type, amount, pos, burst = true) {
  if (amount <= 0) return
  const color = LOOT_COLORS[type] || 0xffffff
  const group = new THREE.Group()
  group.position.copy(pos)
  group.position.y = Math.max(0.45, pos.y)
  if (burst) {
    group.position.x += rnd(-0.7, 0.7)
    group.position.z += rnd(-0.7, 0.7)
  }
  const coreMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.95 })
  const core = new THREE.Mesh(lootGeo, coreMat)
  group.add(core)
  const ring = new THREE.Mesh(lootRingGeo, new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false }))
  ring.rotation.x = Math.PI / 2.5
  group.add(ring)
  const glow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: world.textures.glow,
    color,
    transparent: true,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    opacity: 0.7,
  }))
  glow.scale.set(0.85, 0.85, 1)
  group.add(glow)
  scene.add(group)
  const orb = {
    type,
    amount,
    group,
    core,
    ring,
    glow,
    age: 0,
    settled: false,
    vel: new THREE.Vector3(rnd(-1.8, 1.8), rnd(2.6, 4.2), rnd(-1.8, 1.8)),
    baseY: 0.45,
    phase: rnd(0, TAU),
  }
  GAME.loot.push(orb)
}

function collectOrb(orb) {
  addResource(orb.type, orb.amount)
  bufferLootToast(orb.type, orb.amount)
  spawnSparks(orb.group.position.clone(), LOOT_COLORS[orb.type], 7, 2.2, 0.05)
  audio.pickup(orb.type === 'ember' || orb.type === 'shard')
  scene.remove(orb.group)
  orb.dead = true
}

function gatherNearby() {
  if (GAME.state !== 'playing') return
  let count = 0
  for (const orb of GAME.loot) {
    if (orb.dead) continue
    if (orb.group.position.distanceTo(player.group.position) < 5.4) {
      collectOrb(orb)
      count++
    }
  }
  if (count > 0) {
    showToast('i-key', `Gathered <b>${count}</b> offering${count > 1 ? 's' : ''}`)
    spawnRing(player.group.position.clone().setY(0.05), 0x74e0d4, 0.4, 3.4, 0.5, 0.3)
  }
}

function setSoundLabels() {
  const label = audio.muted ? 'SOUND: OFF' : 'SOUND: ON'
  ui.titleSoundBtn.textContent = label
  ui.pauseSoundBtn.textContent = label
}

function toggleSound() {
  audio.init()
  audio.toggle()
  setSoundLabels()
}

function resetProgression() {
  player.hp = 120
  player.maxHp = 120
  player.stamina = 100
  player.flasks = 3
  player.maxFlasks = 3
  player.level = 1
  player.essence = 0
  player.essenceNext = 80
  player.inventory = { iron: 1, bone: 1, ember: 1, shard: 0 }
  player.upgrades = { blade: false, cuirass: false, charm: false, flasks: 0, whetstones: 0 }
  player.equipment = { weapon: 'Rusted Edge', armor: 'Tattered Leathers', charm: 'Empty Reliquary' }
  player.damage = 18
  player.damageReduction = 0
  player.invuln = 0
  player.attack = null
  player.roll = null
  player.combo = 0
  player.lastAttack = -10
  player.facing = Math.PI
  player.targetFacing = Math.PI
  player.healT = 0
  recalcStats(false)
  player.hp = player.maxHp
  player.flasks = player.maxFlasks
  updateSwordVisuals()
  updateHUD()
}

input.oldString:
  updateSwordVisuals()
  updateHUD()
}

input.newString:
  updateSwordVisuals()
  updateHUD()
}

function removeEntity(entity) {
  if (!entity) return
  scene.remove(entity.group)
  if (entity.bar) scene.remove(entity.bar.group)
}

function clearEntities() {
  for (const e of GAME.enemies) removeEntity(e.rig)
  for (const p of GAME.projectiles) scene.remove(p.group)
  for (const l of GAME.loot) scene.remove(l.group)
  for (const fx of GAME.effects) if (fx.object) scene.remove(fx.object)
  if (GAME.boss) removeEntity(GAME.boss.rig)
  GAME.enemies = []
  GAME.projectiles = []
  GAME.loot = []
  GAME.effects = []
  GAME.boss = null
  GAME.spawnQueue = []
}

function resetWorldObjects() {
  for (const chest of world.chests) {
    chest.opened = false
    chest.openT = 0
    chest.lidPivot.rotation.x = 0
    chest.glow.material.opacity = 0.4
  }
}

function startRun() {
  audio.init()
  hideAllScreens()
  resetProgression()
  clearEntities()
  resetWorldObjects()
  player.group.position.set(0, 0, 16)
  player.group.rotation.set(0, Math.PI, 0)
  avatar.rig.position.set(0, 0, 0)
  avatar.rig.rotation.set(0, 0, 0)
  player.facing = Math.PI
  player.targetFacing = Math.PI
  player.hurtT = 0
  player.invuln = 0
  cameraYaw = 0
  cameraPitch = 0.23
  cameraDistance = 5.8
  camera.position.set(0, 3.3, 22)
  GAME.state = 'playing'
  GAME.phase = 'idle'
  GAME.waveIndex = -1
  GAME.waveKilled = 0
  GAME.waveTotal = 0
  GAME.kills = 0
  GAME.totalShards = 0
  GAME.runTime = 0
  GAME.slowmo = 0
  GAME.shake = 0
  GAME.hitStop = 0
  GAME.clearTimer = 0
  ui.hud.classList.remove('is-hidden')
  ui.touch.classList.toggle('is-hidden', !isTouch)
  ui.bossBar.classList.add('is-hidden')
  ui.interact.classList.add('is-hidden')
  updateHUD()
  setObjective('THE GLOOMWOOD', 'Awaken', 'The dead are waiting.')
  startWave(0)
  if (!isTouch) requestPointerLock()
}

function requestPointerLock() {
  if (isTouch) return
  if (document.pointerLockElement === canvas) return
  try {
    const result = canvas.requestPointerLock()
    if (result && typeof result.catch === 'function') result.catch(() => {})
  } catch {
    // Pointer lock can be unavailable in embeds and automated browsers.
  }
}

function startWave(index) {
  if (index >= WAVES.length) return
  GAME.waveIndex = index
  const wave = WAVES[index]
  if (wave.boss) {
    startBoss()
    return
  }
  GAME.phase = 'combat'
  GAME.waveKilled = 0
  GAME.waveTotal = wave.groups.reduce((sum, [, count]) => sum + count, 0)
  GAME.spawnQueue = []
  for (const [type, count] of wave.groups) {
    for (let i = 0; i < count; i++) GAME.spawnQueue.push(type)
  }
  GAME.spawnTimer = 1.0
  showWaveBanner(wave.kicker, wave.title, wave.sub)
  setObjective(wave.kicker, wave.title, `${wave.objective} — 0 / ${GAME.waveTotal}`)
  updateHUD()
  audio.wave()
}

function startBoss() {
  GAME.phase = 'boss'
  GAME.waveIndex = 3
  GAME.waveKilled = 0
  GAME.waveTotal = 1
  showWaveBanner('FINAL RITE', 'The Bone Warden', 'The Hollow Crown has a keeper.')
  setObjective('FINAL RITE', 'The Bone Warden', 'Break the Hollow Crown')
  audio.bossRoar()
  screenShake(0.4)

  const rig = createBoss(scene, 0, -14.4, world.textures)
  rig.group.position.y = -3.4
  const boss = {
    rig,
    group: rig.group,
    hp: 780,
    maxHp: 780,
    damage: 34,
    speed: 1.9,
    radius: 1.15,
    barY: 4.9,
    state: 'rising',
    timer: 2.0,
    attackCd: 2.2,
    chargeCd: 5.5,
    rise: 0,
    anim: 0,
    walk: 0,
    flash: 0,
    dead: false,
    deathT: 0,
    summoned1: false,
    summoned2: false,
    enraged: false,
    essence: 220,
    facing: 0,
    targetFacing: 0,
    chargeDir: new THREE.Vector3(),
    didHit: false,
  }
  GAME.boss = boss
  ui.bossBar.classList.remove('is-hidden')
  ui.bossFill.style.width = '100%'
  updateHUD()
  spawnMist(new THREE.Vector3(0, 0.4, -14.4), 0x9f3a3a, 6, 2.2)
  window.setTimeout(() => {
    if (GAME.state === 'playing' && GAME.boss === boss) {
      spawnSoulBurst(new THREE.Vector3(0, 1.5, -14.4), 0xff4a3b, 30)
      screenShake(0.3)
    }
  }, 600)
}

function completeWave() {
  if (GAME.phase !== 'combat') return
  GAME.phase = 'cleared'
  GAME.clearTimer = 3.4
  player.hp = Math.min(player.maxHp, player.hp + 20)
  player.flasks = Math.min(player.maxFlasks, player.flasks + 1)
  showWaveBanner('RITE COMPLETE', 'The Gloom Breathes', 'Gather what the dead left behind.')
  setObjective('RITE COMPLETE', 'The way opens', 'Prepare yourself. The next rite stirs.')
  audio.levelUp()
  spawnLoot('iron', 2, player.group.position.clone(), true)
  spawnLoot('bone', 2, player.group.position.clone(), true)
  spawnLoot('ember', 1, player.group.position.clone(), true)
  spawnLoot('shard', 18, player.group.position.clone(), true)
  updateHUD()
}

function checkWaveComplete() {
  if (GAME.phase !== 'combat') return
  if (GAME.spawnQueue.length > 0) return
  const alive = GAME.enemies.some((e) => !e.dead)
  if (!alive) completeWave()
}

function updateWaves(dt) {
  if (GAME.phase === 'combat') {
    if (GAME.spawnQueue.length > 0) {
      GAME.spawnTimer -= dt
      if (GAME.spawnTimer <= 0) {
        const type = GAME.spawnQueue.shift()
        const p = findSpawnPoint()
        spawnEnemy(type, p.x, p.z)
        GAME.spawnTimer = rnd(0.35, 0.72)
      }
    }
    checkWaveComplete()
  } else if (GAME.phase === 'cleared') {
    GAME.clearTimer -= dt
    if (GAME.clearTimer <= 0) {
      if (GAME.waveIndex + 1 < WAVES.length) startWave(GAME.waveIndex + 1)
    }
  }
}

function findSpawnPoint() {
  for (let i = 0; i < 30; i++) {
    const a = rnd(0, TAU)
    const r = rnd(13, 21)
    const x = Math.cos(a) * r
    const z = Math.sin(a) * r
    if (Math.hypot(x - player.group.position.x, z - player.group.position.z) < 8) continue
    let blocked = false
    for (const o of world.obstacles) {
      if (Math.hypot(x - o.x, z - o.z) < o.r + 1.2) {
        blocked = true
        break
      }
    }
    if (!blocked) return { x, z }
  }
  return { x: rnd(-12, 12), z: rnd(-8, 8) }
}

function spawnEnemy(type, x, z) {
  const base = ENEMY_STATS[type]
  const scale = 1 + GAME.waveIndex * 0.1
  const rig = createEnemy(scene, type, x, z, world.textures)
  const e = {
    rig,
    group: rig.group,
    type,
    hp: Math.round(base.hp * scale),
    maxHp: Math.round(base.hp * scale),
    damage: Math.round(base.damage * (1 + GAME.waveIndex * 0.06)),
    speed: base.speed * (1 + GAME.waveIndex * 0.025),
    range: base.range,
    windup: base.windup,
    cooldown: base.cooldown,
    essence: base.essence,
    radius: base.radius,
    barY: base.barY,
    state: 'idle',
    attackState: null,
    attackTimer: 0,
    attackCd: rnd(0.4, 1.4),
    flash: 0,
    stagger: 0,
    dead: false,
    deathT: 0,
    anim: rnd(0, 10),
    walk: 0,
    moving: false,
    facing: 0,
    targetFacing: 0,
    shootCd: rnd(0.5, 1.5),
  }
  rig.bar.fill.scale.x = 1
  rig.bar.fill.position.x = 0
  rig.bar.group.visible = false
  GAME.enemies.push(e)
  spawnMist(new THREE.Vector3(x, 0.25, z), type === 'brute' ? 0xff5a42 : type === 'wisp' ? 0x65cde0 : 0x78d4c7, type === 'brute' ? 2.2 : 1.4, 0.9)
  return e
}

function spawnBossAdds(count) {
  if (!GAME.boss) return
  for (let i = 0; i < count; i++) {
    const a = rnd(0, TAU)
    const x = GAME.boss.group.position.x + Math.cos(a) * rnd(2.5, 4.5)
    const z = GAME.boss.group.position.z + Math.sin(a) * rnd(2.5, 4.5)
    spawnEnemy('thrall', x, z)
  }
  spawnRing(GAME.boss.group.position.clone().setY(0.06), 0xff4034, 0.8, 7, 0.9, 0.5)
}

  spawnRing(GAME.boss.group.position.clone().setY(0.06), 0xff4034, 0.8, 7, 0.9, 0.5)
}

function spawnSparks(pos, color = 0xffffff, count = 10, speed = 4, size = 0.055) {
  const positions = new Float32Array(count * 3)
  const velocities = []
  for (let i = 0; i < count; i++) {
    positions[i * 3] = pos.x
    positions[i * 3 + 1] = pos.y
    positions[i * 3 + 2] = pos.z
    const a = rnd(0, TAU)
    const up = rnd(0.2, 1)
    velocities.push(new THREE.Vector3(Math.cos(a) * rnd(0.4, 1) * speed, up * speed, Math.sin(a) * rnd(0.4, 1) * speed))
  }
  const geo = new THREE.BufferGeometry()
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  const mat = new THREE.PointsMaterial({
    color,
    size,
    map: world.textures.particle,
    transparent: true,
    opacity: 1,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    sizeAttenuation: true,
  })
  const points = new THREE.Points(geo, mat)
  points.frustumCulled = false
  scene.add(points)
  GAME.effects.push({
    object: points,
    life: 0,
    maxLife: rnd(0.45, 0.8),
    update(dt) {
      this.life += dt
      const arr = geo.attributes.position.array
      for (let i = 0; i < count; i++) {
        const v = velocities[i]
        v.y -= 9 * dt
        arr[i * 3] += v.x * dt
        arr[i * 3 + 1] += v.y * dt
        arr[i * 3 + 2] += v.z * dt
      }
      geo.attributes.position.needsUpdate = true
      mat.opacity = clamp(1 - this.life / this.maxLife, 0, 1)
      return this.life < this.maxLife
    },
  })
}

function spawnRing(pos, color, startScale, endScale, duration, opacity = 0.5) {
  const group = new THREE.Group()
  group.position.copy(pos)
  const mesh = new THREE.Mesh(
    new THREE.RingGeometry(0.92, 1.0, 48),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
  )
  mesh.rotation.x = -Math.PI / 2
  group.add(mesh)
  scene.add(group)
  GAME.effects.push({
    object: group,
    life: 0,
    maxLife: duration,
    startScale,
    endScale,
    opacity,
    update(dt) {
      this.life += dt
      const p = clamp(this.life / this.maxLife, 0, 1)
      const s = lerp(this.startScale, this.endScale, easeOut(p))
      group.scale.set(s, s, s)
      mesh.material.opacity = this.opacity * (1 - p)
      return this.life < this.maxLife
    },
  })
}

function spawnMist(pos, color = 0x8eb5b6, scale = 1.6, duration = 1.1) {
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
    map: world.textures.fog,
    color,
    transparent: true,
    opacity: 0.28,
    depthWrite: false,
    blending: THREE.NormalBlending,
    rotation: rnd(0, TAU),
  }))
  sprite.position.copy(pos)
  sprite.scale.set(scale, scale * 0.55, 1)
  scene.add(sprite)
  GAME.effects.push({
    object: sprite,
    life: 0,
    maxLife: duration,
    update(dt) {
      this.life += dt
      const p = clamp(this.life / this.maxLife, 0, 1)
      const s = scale * (1 + p * 1.6)
      sprite.scale.set(s, s * 0.55, 1)
      sprite.position.y += dt * 0.28
      sprite.material.opacity = 0.3 * (1 - p)
      sprite.material.rotation += dt * 0.25
      return this.life < this.maxLife
    },
  })
}

function spawnSlash(pos, facing, color = 0x8fe6da, heavy = false) {
  const group = new THREE.Group()
  group.position.copy(pos)
  group.position.y = heavy ? 0.7 : 1.05
  group.rotation.y = facing - Math.PI / 2
  const arc = new THREE.Mesh(
    new THREE.RingGeometry(heavy ? 0.5 : 0.55, heavy ? 1.9 : 1.5, 28, 1, heavy ? -1.15 : -0.8, heavy ? 2.3 : 1.6),
    new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: heavy ? 0.55 : 0.42,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide,
    })
  )
  arc.rotation.x = -Math.PI / 2
  group.add(arc)
  const flash = new THREE.Sprite(new THREE.SpriteMaterial({
    map: world.textures.glow,
    color,
    transparent: true,
    opacity: 0.35,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  }))
  flash.position.set(0, 0.05, 0)
  flash.scale.set(heavy ? 2.2 : 1.4, heavy ? 2.2 : 1.4, 1)
  group.add(flash)
  scene.add(group)
  GAME.effects.push({
    object: group,
    life: 0,
    maxLife: heavy ? 0.42 : 0.3,
    update(dt) {
      this.life += dt
      const p = clamp(this.life / this.maxLife, 0, 1)
      group.rotation.z += dt * (heavy ? 1.2 : 2.2)
      const s = 1 + easeOut(p) * (heavy ? 0.65 : 0.35)
      group.scale.set(s, s, s)
      arc.material.opacity = (heavy ? 0.55 : 0.42) * (1 - p)
      flash.material.opacity = 0.3 * (1 - p)
      return this.life < this.maxLife
    },
  })
}

function spawnSoulBurst(pos, color = 0x74e0d4, count = 24) {
  spawnSparks(pos, color, count, 3.4, 0.07)
  spawnRing(pos.clone().setY(0.06), color, 0.2, 2.4, 0.8, 0.35)
}

function spawnProjectile(origin, target, damage) {
