import * as THREE from 'three'

const TAU = Math.PI * 2

const rnd = (min, max) => min + Math.random() * (max - min)
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)]

function canvasTexture(size, draw, repeat = 1) {
  const canvas = document.createElement('canvas')
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext('2d')
  draw(ctx, size)
  const tex = new THREE.CanvasTexture(canvas)
  tex.wrapS = THREE.RepeatWrapping
  tex.wrapT = THREE.RepeatWrapping
  tex.repeat.set(repeat, repeat)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 8
  return tex
}

function groundTexture() {
  return canvasTexture(512, (ctx, size) => {
    const img = ctx.createImageData(size, size)
    for (let i = 0; i < img.data.length; i += 4) {
      const x = (i / 4) % size
      const y = Math.floor(i / 4 / size)
      const n = Math.sin(x * 0.07) * Math.cos(y * 0.06) * 8
      const grain = (Math.random() - 0.5) * 28
      const moss = Math.sin(x * 0.02 + 1.4) * Math.cos(y * 0.023) * 7
      img.data[i] = 25 + grain + n + moss * 0.5
      img.data[i + 1] = 28 + grain + n * 0.6 + moss
      img.data[i + 2] = 23 + grain * 0.7
      img.data[i + 3] = 255
    }
    ctx.putImageData(img, 0, 0)

    ctx.globalAlpha = 0.25
    for (let i = 0; i < 100; i++) {
      ctx.strokeStyle = Math.random() > 0.45 ? '#0d100e' : '#394036'
      ctx.lineWidth = rnd(0.4, 1.6)
      ctx.beginPath()
      let x = rnd(0, size)
      let y = rnd(0, size)
      ctx.moveTo(x, y)
      for (let j = 0; j < 4; j++) {
        x += rnd(-22, 22)
        y += rnd(-18, 18)
        ctx.lineTo(x, y)
      }
      ctx.stroke()
    }

    ctx.globalAlpha = 0.3
    for (let i = 0; i < 90; i++) {
      const x = rnd(0, size)
      const y = rnd(0, size)
      const r = rnd(1, 4)
      ctx.fillStyle = pick(['#4a4d42', '#242a22', '#111410', '#3b3d33'])
      ctx.beginPath()
      ctx.ellipse(x, y, r, r * 0.7, rnd(0, TAU), 0, TAU)
      ctx.fill()
    }

    const grad = ctx.createRadialGradient(size / 2, size / 2, size * 0.08, size / 2, size / 2, size * 0.7)
    grad.addColorStop(0, 'rgba(0,0,0,0)')
    grad.addColorStop(1, 'rgba(0,0,0,0.42)')
    ctx.globalAlpha = 1
    ctx.fillStyle = grad
    ctx.fillRect(0, 0, size, size)
  }, 18)
}

function stoneTexture() {
  return canvasTexture(256, (ctx, size) => {
    ctx.fillStyle = '#343630'
    ctx.fillRect(0, 0, size, size)
    const img = ctx.getImageData(0, 0, size, size)
    for (let i = 0; i < img.data.length; i += 4) {
      const g = (Math.random() - 0.5) * 24
      img.data[i] += g
      img.data[i + 1] += g
      img.data[i + 2] += g * 0.8
    }
    ctx.putImageData(img, 0, 0)
    ctx.globalAlpha = 0.36
    for (let i = 0; i < 24; i++) {
      ctx.strokeStyle = '#171a16'
      ctx.lineWidth = rnd(0.5, 2)
      ctx.beginPath()
      ctx.moveTo(rnd(0, size), rnd(0, size))
      ctx.lineTo(rnd(0, size), rnd(0, size))
      ctx.stroke()
    }
    ctx.globalAlpha = 0.2
    for (let i = 0; i < 28; i++) {
      ctx.fillStyle = '#66705e'
      ctx.beginPath()
      ctx.arc(rnd(0, size), rnd(0, size), rnd(1, 4), 0, TAU)
