export function createPlayer(scene, textures) {
  const group = new THREE.Group()
  group.position.set(0, 0, 16)
  const rig = new THREE.Group()
  group.add(rig)

  const leather = mat(0x3a2b22, { roughness: 0.88 })
  const leatherDark = mat(0x241a15, { roughness: 0.94 })
  const darkCloth = mat(0x2b353c, { roughness: 0.94, side: THREE.DoubleSide, emissive: 0x0b1114, emissiveIntensity: 0.4 })
  const innerCloth = mat(0x35433f, { roughness: 0.92, emissive: 0x0a1110, emissiveIntensity: 0.28 })
  const steel = mat(0xb3bcbc, { roughness: 0.33, metalness: 0.88, emissive: 0x1a2222, emissiveIntensity: 0.3 })
  const darkSteel = mat(0x4c5656, { roughness: 0.46, metalness: 0.78 })
  const brass = mat(0xb08a45, { roughness: 0.36, metalness: 0.82, emissive: 0x2b1b06, emissiveIntensity: 0.25 })
  const skin = mat(0xd2ad95, { roughness: 0.62 })
  const skinShadow = mat(0xb98f78, { roughness: 0.72 })
  const hair = mat(0x5c3422, { roughness: 0.72, emissive: 0x1a0b06, emissiveIntensity: 0.32 })
  const lips = mat(0x9b5b58, { roughness: 0.58 })
  const eyeWhite = mat(0xe8e3da, { roughness: 0.3 })
  const socket = mat(0x3a2a24, { roughness: 0.9 })
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0x7ce3d7 })
  const pupilMat = new THREE.MeshBasicMaterial({ color: 0x101414 })
  const flashMats = [leather, leatherDark, darkCloth, innerCloth, steel, darkSteel, brass, skin, hair]

  // Hips / pelvis
  const hips = new THREE.Group()
  hips.position.y = 1.02
  rig.add(hips)

  const pelvis = mesh(new THREE.CylinderGeometry(0.2, 0.175, 0.26, 14), leatherDark, 0, 0.02, 0)
  hips.add(pelvis)

  const belt = mesh(new THREE.CylinderGeometry(0.215, 0.222, 0.09, 14), leather, 0, 0.14, 0)
  hips.add(belt)
  const buckle = mesh(new THREE.BoxGeometry(0.1, 0.08, 0.03), brass, 0, 0.14, 0.216)
  hips.add(buckle)

  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU
    const stud = mesh(new THREE.SphereGeometry(0.012, 6, 5), brass, Math.sin(a) * 0.215, 0.14, Math.cos(a) * 0.215, false)
    hips.add(stud)
  }

  // Leather tassets — a short skirt of leather panels, not a cloak
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * TAU + 0.22
    const panelMat = i % 2 ? leatherDark : leather
    const panel = mesh(new THREE.BoxGeometry(0.105, 0.24, 0.025), panelMat, Math.sin(a) * 0.19, -0.02, Math.cos(a) * 0.19)
    panel.rotation.y = a
    panel.rotation.x = Math.sin(a) * 0.04
    hips.add(panel)
  }

  // Hip pouch
  const pouch = mesh(new THREE.BoxGeometry(0.095, 0.12, 0.055), leather, -0.19, 0.03, 0.09)
  pouch.rotation.y = 0.42
  hips.add(pouch)
  const pouchFlap = mesh(new THREE.BoxGeometry(0.1, 0.03, 0.06), leatherDark, -0.19, 0.09, 0.09)
  pouchFlap.rotation.y = 0.42
  hips.add(pouchFlap)

  // Legs
  const leftLeg = new THREE.Group()
  leftLeg.position.set(-0.115, 0, 0)
  const rightLeg = new THREE.Group()
  rightLeg.position.set(0.115, 0, 0)
  hips.add(leftLeg, rightLeg)

  for (const [leg, side] of [[leftLeg, -1], [rightLeg, 1]]) {
    const thigh = limb(0.46, 0.088, 0.068, darkCloth)
    thigh.position.y = -0.23
    leg.add(thigh)
    const thighStrap = mesh(new THREE.CylinderGeometry(0.078, 0.075, 0.045, 10), leather, 0, -0.2, 0)
    leg.add(thighStrap)
    const knee = mesh(new THREE.SphereGeometry(0.072, 10, 8), darkSteel, 0, -0.47, 0.028)
    knee.scale.set(1, 0.72, 0.82)
    leg.add(knee)
    const shin = limb(0.44, 0.062, 0.046, leatherDark)
    shin.position.y = -0.69
    leg.add(shin)
    const bootCuff = mesh(new THREE.CylinderGeometry(0.072, 0.078, 0.12, 10), leather, 0, -0.82, 0)
    leg.add(bootCuff)
    const boot = mesh(new THREE.BoxGeometry(0.14, 0.14, 0.26), leather, 0, -0.95, 0.05)
    leg.add(boot)
    const toe = mesh(new THREE.BoxGeometry(0.135, 0.075, 0.1), leatherDark, 0, -0.982, 0.17)
    leg.add(toe)
    const legPlate = mesh(new THREE.BoxGeometry(0.095, 0.2, 0.022), darkSteel, side * 0.008, -0.64, 0.07)
    legPlate.rotation.x = -0.05
    leg.add(legPlate)
  }

  // Torso — fitted waist, narrow shoulders, wider hips
  const torso = new THREE.Group()
  torso.position.y = 0.18
  hips.add(torso)

  const waist = mesh(new THREE.CylinderGeometry(0.18, 0.158, 0.3, 14), darkCloth, 0, 0.14, 0)
  torso.add(waist)

  const ribcage = mesh(new THREE.CylinderGeometry(0.215, 0.175, 0.34, 14), leather, 0, 0.43, 0)
  torso.add(ribcage)

  // Subtle chest shaping beneath the breastplate
  const chestForm = mesh(new THREE.SphereGeometry(0.182, 16, 12), leather, 0, 0.47, 0.035)
  chestForm.scale.set(1.08, 0.76, 0.66)
  torso.add(chestForm)

  const breastplate = mesh(new THREE.SphereGeometry(0.205, 16, 12), darkSteel, 0, 0.46, 0.045)
  breastplate.scale.set(1.02, 0.78, 0.56)
  torso.add(breastplate)

  const sternum = mesh(new THREE.BoxGeometry(0.032, 0.24, 0.022), brass, 0, 0.45, 0.16)
  torso.add(sternum)

  for (let i = 0; i < 5; i++) {
    const lace = mesh(new THREE.SphereGeometry(0.012, 6, 5), brass, 0, 0.14 + i * 0.055, 0.17, false)
    torso.add(lace)
  }

  const strap = mesh(new THREE.BoxGeometry(0.042, 0.5, 0.018), leatherDark, -0.08, 0.36, 0.17)
  strap.rotation.z = 0.06
  torso.add(strap)
  const strap2 = mesh(new THREE.BoxGeometry(0.042, 0.5, 0.018), leatherDark, 0.08, 0.36, 0.17)
  strap2.rotation.z = -0.06
  torso.add(strap2)

  const collar = mesh(new THREE.TorusGeometry(0.14, 0.026, 6, 14), darkCloth, 0, 0.64, 0)
  collar.rotation.x = Math.PI / 2
  torso.add(collar)
  const collarBack = mesh(new THREE.CylinderGeometry(0.15, 0.17, 0.13, 14, 1, true), darkCloth, 0, 0.68, -0.025)
  torso.add(collarBack)

  const yoke = mesh(new THREE.BoxGeometry(0.42, 0.07, 0.16), leather, 0, 0.62, 0)
  torso.add(yoke)

  // Shoulder pauldrons
  for (const side of [-1, 1]) {
    const pauldron = mesh(new THREE.SphereGeometry(0.12, 12, 9), darkSteel, side * 0.265, 0.58, 0)
    pauldron.scale.set(1.18, 0.58, 0.96)
    torso.add(pauldron)
    const ridge = mesh(new THREE.TorusGeometry(0.113, 0.014, 5, 12), brass, side * 0.265, 0.6, 0)
    ridge.rotation.x = Math.PI / 2
    ridge.scale.y = 0.88
    torso.add(ridge)
  }

  // Arms — slimmer, with leather sleeves and steel bracers
  const leftArm = new THREE.Group()
  leftArm.position.set(-0.275, 0.57, 0)
  const rightArm = new THREE.Group()
  rightArm.position.set(0.275, 0.57, 0)
  torso.add(leftArm, rightArm)

  for (const [arm, side] of [[leftArm, -1], [rightArm, 1]]) {
    const upper = limb(0.34, 0.061, 0.047, darkCloth)
    upper.position.y = -0.17
    arm.add(upper)
    const elbow = mesh(new THREE.SphereGeometry(0.055, 8, 6), leather, 0, -0.35, 0)
    arm.add(elbow)
    const fore = new THREE.Group()
    fore.position.y = -0.36
    arm.add(fore)
    const foreMesh = limb(0.3, 0.052, 0.039, leather)
    foreMesh.position.y = -0.15
    fore.add(foreMesh)
    const bracer = mesh(new THREE.CylinderGeometry(0.057, 0.049, 0.16, 10), darkSteel, 0, -0.2, 0)
    fore.add(bracer)
    const bracerRim = mesh(new THREE.TorusGeometry(0.056, 0.008, 4, 12), brass, 0, -0.12, 0)
    bracerRim.rotation.x = Math.PI / 2
    fore.add(bracerRim)
    const hand = mesh(new THREE.BoxGeometry(0.07, 0.1, 0.062), leatherDark, 0, -0.34, 0.01)
    fore.add(hand)
    arm.userData.fore = fore
  }

  // Head — feminine proportions with a more detailed face
  const head = new THREE.Group()
  head.position.y = 0.77
  torso.add(head)

  const neck = mesh(new THREE.CylinderGeometry(0.05, 0.062, 0.13, 10), skin, 0, -0.06, 0)
  head.add(neck)

  const face = mesh(new THREE.SphereGeometry(0.145, 18, 14), skin, 0, 0.05, 0.012)
  face.scale.set(0.84, 1.08, 0.9)
  head.add(face)

  const jaw = mesh(new THREE.SphereGeometry(0.085, 14, 10), skin, 0, -0.035, 0.035)
  jaw.scale.set(1.0, 0.78, 0.9)
  head.add(jaw)

  for (const side of [-1, 1]) {
    const cheek = mesh(new THREE.SphereGeometry(0.03, 8, 6), skinShadow, side * 0.07, 0.025, 0.075, false)
    cheek.scale.set(0.9, 0.7, 0.55)
    head.add(cheek)
    const ear = mesh(new THREE.SphereGeometry(0.028, 8, 6), skin, side * 0.123, 0.045, 0.0)
    ear.scale.set(0.55, 1.0, 0.58)
    head.add(ear)
  }

  const nose = mesh(new THREE.ConeGeometry(0.023, 0.052, 7), skin, 0, 0.032, 0.132)
  nose.rotation.x = Math.PI / 2
  head.add(nose)

  const upperLip = mesh(new THREE.BoxGeometry(0.052, 0.008, 0.016), lips, 0, -0.035, 0.128)
  head.add(upperLip)
  const lowerLip = mesh(new THREE.BoxGeometry(0.046, 0.01, 0.016), lips, 0, -0.048, 0.127)
  head.add(lowerLip)

  for (const side of [-1, 1]) {
    const socketBall = mesh(new THREE.SphereGeometry(0.031, 10, 8), socket, side * 0.051, 0.075, 0.115, false)
    socketBall.scale.set(1.15, 0.68, 0.42)
    head.add(socketBall)
    const white = mesh(new THREE.SphereGeometry(0.023, 10, 8), eyeWhite, side * 0.051, 0.075, 0.132, false)
    white.scale.set(1.0, 0.85, 0.8)
    head.add(white)
    const iris = mesh(new THREE.SphereGeometry(0.011, 8, 6), eyeMat, side * 0.051, 0.073, 0.148, false)
    head.add(iris)
    const pupil = mesh(new THREE.SphereGeometry(0.005, 6, 5), pupilMat, side * 0.051, 0.073, 0.155, false)
    head.add(pupil)
    const brow = mesh(new THREE.BoxGeometry(0.044, 0.007, 0.012), hair, side * 0.052, 0.112, 0.128, false)
    brow.rotation.z = side * 0.12
    head.add(brow)
  }

  // Hair: cap, fringe, side locks, and a long braid down the back
  const hairCap = mesh(new THREE.SphereGeometry(0.157, 18, 14), hair, 0, 0.083, -0.052)
  hairCap.scale.set(1.04, 1.02, 0.98)
  head.add(hairCap)

  const hairBack = mesh(new THREE.SphereGeometry(0.135, 16, 12), hair, 0, -0.005, -0.075)
  hairBack.scale.set(1.0, 1.12, 0.85)
  head.add(hairBack)

  for (const side of [-1, 1]) {
    const lock = mesh(new THREE.SphereGeometry(0.045, 10, 8), hair, side * 0.113, 0.018, 0.008)
    lock.scale.set(0.62, 2.0, 0.62)
    lock.rotation.z = side * 0.1
    head.add(lock)
  }

  const fringe = mesh(new THREE.SphereGeometry(0.05, 10, 8), hair, -0.01, 0.143, 0.1)
  fringe.scale.set(1.55, 0.42, 0.7)
  fringe.rotation.z = -0.08
  head.add(fringe)

  const braid = new THREE.Group()
  braid.position.set(0, 0.02, -0.11)
  head.add(braid)
  for (let i = 0; i < 6; i++) {
    const r = 0.054 - i * 0.006
    const seg = mesh(new THREE.SphereGeometry(r, 10, 8), hair, Math.sin(i * 0.7) * 0.018, -0.07 - i * 0.082, -0.02 - i * 0.008)
    seg.scale.set(1.0, 1.2, 1.0)
    braid.add(seg)
  }
  const braidTie = mesh(new THREE.TorusGeometry(0.028, 0.008, 5, 10), brass, 0, -0.555, -0.06)
  braidTie.rotation.x = Math.PI / 2
  braid.add(braidTie)

  // Circlet
  const circlet = mesh(new THREE.TorusGeometry(0.146, 0.006, 4, 18), brass, 0, 0.15, -0.01)
  circlet.rotation.x = Math.PI / 2
  head.add(circlet)
  const circletGem = mesh(new THREE.SphereGeometry(0.014, 8, 6), eyeMat, 0, 0.15, 0.14, false)
  head.add(circletGem)

  const eyeGlow = glowSprite(textures.glow, 0x68d9ce, 0.24, 0.22)
  eyeGlow.position.set(0, 0.075, 0.16)
  head.add(eyeGlow)

  // Sword
  const sword = new THREE.Group()
  sword.position.set(0, -0.34, 0.02)
  sword.rotation.z = -0.15
  rightArm.userData.fore.add(sword)

  const grip = mesh(new THREE.CylinderGeometry(0.025, 0.028, 0.22, 8), leather, 0, 0.04, 0)
  sword.add(grip)
  const pommel = mesh(new THREE.SphereGeometry(0.05, 8, 6), brass, 0, -0.08, 0)
  sword.add(pommel)
  const guard = mesh(new THREE.BoxGeometry(0.27, 0.04, 0.055), darkSteel, 0, 0.16, 0)
  sword.add(guard)
  const blade = mesh(new THREE.BoxGeometry(0.068, 0.98, 0.016), steel, 0, 0.67, 0)
  sword.add(blade)
  const bladeTip = mesh(new THREE.ConeGeometry(0.039, 0.15, 4), steel, 0, 1.22, 0)
  bladeTip.rotation.y = Math.PI / 4
  sword.add(bladeTip)
  const edge = mesh(new THREE.BoxGeometry(0.016, 0.96, 0.004), new THREE.MeshBasicMaterial({ color: 0x6f8f8d }), 0, 0.67, 0.01, false)
  sword.add(edge)
  const swordGlow = glowSprite(textures.glow, 0x62c7bc, 0.5, 0.0)
  swordGlow.position.y = 0.67
  sword.add(swordGlow)

  // Lantern on the left hip
  const lantern = new THREE.Group()
  lantern.position.set(-0.235, 0.02, 0.07)
  hips.add(lantern)
  const lanternBody = mesh(new THREE.CylinderGeometry(0.045, 0.052, 0.12, 8), darkSteel, 0, 0, 0)
  lantern.add(lanternBody)
  const lanternCap = mesh(new THREE.CylinderGeometry(0.055, 0.045, 0.025, 8), brass, 0, 0.07, 0)
  lantern.add(lanternCap)
  const lanternGlow = glowSprite(textures.glow, 0xffa95a, 0.45, 0.65)
  lanternGlow.position.y = 0
  lantern.add(lanternGlow)
  const lanternLight = new THREE.PointLight(0xff9f55, 0.72, 5.0, 2)
  lanternLight.position.y = 0
  lantern.add(lanternLight)

  // Cool rim light so the silhouette stays readable against the gloom
  const rimLight = new THREE.PointLight(0x9fd6e4, 2.0, 7, 2)
  rimLight.position.set(0.75, 2.5, -1.9)
  group.add(rimLight)

  // Grounding shadow
  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.38, 20),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.3, depthWrite: false })
  )
  shadow.rotation.x = -Math.PI / 2
  shadow.position.y = 0.01
  group.add(shadow)

  group.userData.rig = rig
  scene.add(group)

  return {
    group,
    rig,
    hips,
    torso,
    head,
    leftArm,
    rightArm,
    leftLeg,
    rightLeg,
    leftFore: leftArm.userData.fore,
    rightFore: rightArm.userData.fore,
    sword,
    edge,
    swordGlow,
    lantern,
    lanternLight,
    eyeGlow,
    eyeMat,
    flashMats,
    materials: { steel, brass, darkCloth, leather, innerCloth, darkSteel },
  }
}
